-- Add a city field to vendors and seed one vendor per top-5 city in each
-- US state + DC (255 cities), mirroring migration 0007 for venues, so
-- vendors can be filtered/searched by city as a drill-down under the
-- existing state filter (useful for "vendors near your venue").
alter table vendors add column if not exists city text;

